\question[8] On a certain day, the temperature at 2 p.m.\ is $25^\circ$C. The temperature changes after each hour from 2 p.m.\ to 5 p.m.\ are recorded as follows. (A decrease in temperature is represented by a negative number.)

\begin{center}
\begin{tabular}{|c|c|}
\hline
\textbf{Time} & \textbf{Temperature change ($^\circ$C)} \\
\hline
2 p.m. to 3 p.m. & $-1.4$ \\
3 p.m. to 4 p.m. & $+0.6$ \\
4 p.m. to 5 p.m. & $-1.2$ \\
\hline
\end{tabular}
\end{center}

\begin{parts}
    \part Find the temperatures at
    \begin{subparts}
        \subpart 3 p.m.,
        \subpart 4 p.m.,
        \subpart 5 p.m.
    \end{subparts}
    \begin{solutionorlines}[3cm]
    \end{solutionorlines}

    \part If the temperature at 7 p.m.\ is $22.6^\circ$C and the temperature changes from 5 p.m.\ to 6 p.m.\ and from 6 p.m.\ to 7 p.m.\ are the same, Candy claims that the temperature at 6 p.m.\ is higher than the temperature at 2 p.m.\ Do you agree? Explain your answer.

    \begin{solutionorlines}[4cm]
    \end{solutionorlines}
\end{parts}

\question[8] It is given that $T_n$ is the general term of a sequence.
\begin{parts}
    \part Determine what kind of sequence it is.

    \begin{solutionorlines}[2cm]
    \end{solutionorlines}

    \part The sum of the first $n$ terms of the sequence is given by the following formula.
    \[
    S_n = \sum_{k=1}^{n} T_k = \dfrac{n(n+1)(2n+1)}{6}
    \]
    \begin{subparts}
        \subpart Find the values of $S(10)$, $S(19)$ and $S(20)$.
        \begin{solutionorlines}[2cm]
        \end{solutionorlines}
        \subpart Hence, find the values of $4 + 16 + 36 + 64 + \cdots + 400$ and $1^3 + 2^3 + 3^3 + \cdots + 19^3$.
        \begin{solutionorlines}[4cm]
        \end{solutionorlines}
    \end{subparts}
\end{parts}

